def find_minimal_edit(s_in, s_out):
    """Find the smallest change needed to convert s_in to s_out"""
    # Simple approach: find first differing position and determine what needs to be added/removed
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    pos = 0
    while pos < min_len and s_in[pos] == s_out[pos]:
        pos += 1

    if pos >= len(s_in) and pos >= len(s_out):
        return None, None, -1

    # If we're at the end of s_in but s_out is longer
    if pos >= len(s_in):
        return "", s_out[pos:], pos

    # If we're at the end of s_out but s_in is longer  
    if pos >= len(s_out):
        return s_in[pos:], "", pos

    # Both strings continue - check if it's insertion/deletion or substitution
    # Try deletion case
    if len(s_in) > len(s_out):
        # Check if s_out is substring of s_in starting at pos
        if s_out[pos:] == s_in[pos+len(s_in)-len(s_out):]:
            return s_in[pos:pos+len(s_in)-len(s_out)+1], "", pos
        else:
            # Substitution case
            return s_in[pos], s_out[pos], pos
    elif len(s_in) < len(s_out):
        # Insertion case
        if s_in[pos:] == s_out[pos+1:]:
            return "", s_out[pos:pos+1], pos
        else:
            # Substitution case
            return s_in[pos], s_out[pos], pos
    else:
        # Same length - substitution
        return s_in[pos], s_out[pos], pos

